// vertical-slide creates a sliding separator between the left and right elements.
// e.g.:
// <div id="header">Some content</div>
// <div vertical-slide top="#header" bottom="#footer"></div>
// <div id="footer">Some footer</div>
directive('verticalSlide', ['editor',
    function(editor) {
        return function(scope, elm, attrs) {
            // The lesson is the inline-start pane and the editor is the
            // inline-end pane. Store and apply the lesson's logical width so
            // the same splitter contract works in both LTR and RTL layouts.
            var moveTo = function(size) {
                var max = elm.parent()[0].getBoundingClientRect().width;
                if (size < 0) {
                    size = 0;
                }
                if (size > max) {
                    size = max;
                }
                elm.css({
                    'inset-inline-start': size,
                    'inset-inline-end': 'auto'
                });
                $(attrs.left).width(size);
                $(attrs.right).css({
                    'inset-inline-start': size,
                    'inset-inline-end': 0
                });
                editor.x = size;
            };

            elm.draggable({
                axis: 'x',
                drag: function(event) {
                    var bounds = elm.parent()[0].getBoundingClientRect();
                    var size = document.documentElement.dir === 'rtl'
                        ? bounds.right - event.clientX
                        : event.clientX - bounds.left;
                    moveTo(size);
                    return true;
                },
                containment: 'parent',
            });

            if (editor.x !== undefined) {
                moveTo(editor.x);
            }
        };
    }
]).

// horizontal-slide creates a sliding separator between the top and bottom elements.
// <div id="menu">Some menu</div>
// <div vertical-slide left="#menu" bottom="#content"></div>
// <div id="content">Some content</div>
directive('horizontal-slide', ['editor',
    function(editor) {
        return function(scope, elm, attrs) {
            var moveTo = function(y) {
                var top = $(attrs.top).offset().top;
                if (y < top) {
                    y = top;
                }
                elm.css('top', y - top);
                $(attrs.top).height(y - top);
                $(attrs.bottom).offset({
                    top: y,
                    height: 0
                });
                editor.y = y;
            };
            elm.draggable({
                axis: 'y',
                drag: function(event) {
                    moveTo(event.clientY);
                    return true;
                },
                containment: 'parent',
            });

            if (editor.y !== undefined) {
                moveTo(editor.y);
            }
        };
    }
]).

