/**
 * toggleTheme switches the preferred color scheme between auto, light, and dark.
 */
function toggleTheme() {
    let nextTheme = 'dark';
    const theme = document.documentElement.getAttribute('data-theme');
    if (theme === 'dark') {
      nextTheme = 'light';
    } else if (theme === 'light') {
      nextTheme = 'auto';
    }
    let domain = '';
    if (location.hostname === 'go.dev') {
      // Include subdomains to apply the setting to pkg.go.dev.
      domain = 'domain=.go.dev;';
    }
    document.documentElement.setAttribute('data-theme', nextTheme);
    document.cookie =
    `prefers-color-scheme=${nextTheme};${domain}path=/;max-age=31536000;`;
  }


function setThemeButtons() {
    for (const el of document.querySelectorAll('.js-toggleTheme')) {
      el.addEventListener('click', () => {
        toggleTheme();
      });
    }
}

function setLanguageMenuDismiss() {
    const languageMenus = document.querySelectorAll('.header-language');
    if (languageMenus.length === 0) {
      return;
    }
    document.addEventListener('click', (event) => {
      for (const menu of languageMenus) {
        if (menu.open && !menu.contains(event.target)) {
          menu.open = false;
        }
      }
    });
    document.addEventListener('keydown', (event) => {
      if (event.key !== 'Escape') {
        return;
      }
      for (const menu of languageMenus) {
        if (!menu.open) {
          continue;
        }
        menu.open = false;
        const summary = menu.querySelector('summary');
        if (summary) {
          summary.focus();
        }
      }
    });
}

setThemeButtons();
setLanguageMenuDismiss();

